<?php
require __DIR__.'/../inc/bootstrap.php';
$q=trim((string)($_GET['q']??''));$loc=trim((string)($_GET['location']??''));$status=(int)($_GET['status']??0);$archived=(string)($_GET['archived']??'0');$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$where=['1=1'];$params=[];if($q!==''){$where[]='(a.tracking_code LIKE ? OR a.full_name LIKE ? OR a.email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($loc!==''&&isset(locations()[$loc])){$where[]='a.location=?';$params[]=$loc;}if($status>0){$where[]='a.current_status_id=?';$params[]=$status;}if($archived==='1')$where[]='a.is_archived=1';elseif($archived==='all'){}else $where[]='a.is_archived=0';if($from!==''){$where[]='DATE(a.created_at)>=?';$params[]=$from;}if($to!==''){$where[]='DATE(a.created_at)<=?';$params[]=$to;}
$stmt=$db->prepare('SELECT a.*,s.name status_name FROM applications a LEFT JOIN statuses s ON s.id=a.current_status_id WHERE '.implode(' AND ',$where).' ORDER BY a.created_at DESC');$stmt->execute($params);$rows=$stmt->fetchAll();$keys=[];$labelMap=[];foreach($rows as &$r){$r['_answers']=json_decode($r['answers_json'],true)?:[];$snap=json_decode($r['form_snapshot_json'],true)?:[];foreach($snap['fields']??[] as $f){$labelMap[$f['field_key']]=$f['label'];}foreach(array_keys($r['_answers']) as $k)$keys[$k]=true;}unset($r);$keys=array_keys($keys);
